-- Callback · importa el historial real de castings de Fifth Management (sept 2025 – nov 2026)
-- Pégalo en Supabase › SQL Editor › New query y pulsa Run.
-- Si te registraste en Callback con otro email, cámbialo en la línea de abajo.
-- Se puede ejecutar varias veces: primero borra lo importado antes, nunca lo que creaste tú.
do $$
declare uid uuid;
begin
  select id into uid from auth.users where email = 'salvatori.luc@gmail.com';
  if uid is null then raise exception 'No hay ninguna cuenta de Callback con ese email'; end if;
  delete from public.castings where user_id = uid and source = 'importado';
  -- Completa tu perfil con lo que aparece en los emails (no toca nombre, edad ni el resto)
  on conflict (user_id) do update set data = public.profiles.data || excluded.data;
  raise notice 'Importados % castings', 148;
end $$;
